// Read-only cloud handshake/capability probe. Serial is read from stdin, never logged.
#include "dvrip.h"
#include <iostream>
int main(int argc,char **argv){QCoreApplication app(argc,argv);std::string serial;std::getline(std::cin,serial);std::atomic_bool stop{false};try{xm::cloud::Transport t(stop,[](const QString &s){std::cout<<s.toStdString()<<std::endl;});t.open(QString::fromStdString(serial));QJsonObject claim{{"Name","OPMonitor"},{"SessionID","0x1"},{"OPMonitor",QJsonObject{{"Action","Claim"},{"Parameter",QJsonObject{{"Channel",0},{"CombinMode","CONNECT_ALL"},{"StreamType","Main"},{"TransMode","TCP"}}}}}};auto body=QJsonDocument(claim).toJson(QJsonDocument::Compact)+"\n";auto h=xm::header(99999,0,1413,body.size());h[12]=99;t.write(h+body);auto reply=t.read(20);auto payload=t.read(xm::payloadSize(reply));if(!payload.trimmed().startsWith('{'))payload=xm::cloud::aesDecode(payload,xm::cloud::wrapperKey());auto cap=QJsonDocument::fromJson(payload).object();if(cap.value("Ret").toInt()!=100)throw std::runtime_error("Capability request rejected");std::cout<<"Recorder capability received: RSA="<<cap["LoginEncryptionType"].toObject()["RSA"].toBool()<<", bits="<<cap["Bits"].toInt()<<". No credentials sent.\n";return 0;}catch(const std::exception &e){std::cerr<<e.what()<<"\n";return 1;}}
